/*
 * A131404  a(n) = 2*A131402(n) - 1.
 * https://oeis.org/A131404
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl, easy
 * Formula:   not stated
 * Range:     u8 n <= 47, u16 n <= 158, u32 n <= 575, u64 n <= 1274,
 *            u128 n <= 1274, big any n
 * Helpers:   binomial
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A131404
 *  a(n) is the nth element of the triangle generated by
 *
 *      T(r,k) = 4*C(r,k) + 1
 *            - 2*C(floor((r+k)/2), k)
 *            - 2*C(r - floor((k+1)/2), floor(k/2))
 *
 *  where rows r run from 0 upwards and k runs from 0 to r.
 *  n is a linear index in row-major order:
 *      a(0)=T(0,0), a(1)=T(1,0), a(2)=T(1,1), a(3)=T(2,0), ...
 *
 *  Copyright © 2023
 *
 *  Requires utils/binomial.h for the binomial function.
 */
#include <stdint.h>
#include "../utils/binomial.h"

/* integer square root: floor(sqrt(x)) for 64‑bit values */
static idx_t isqrt_u64(idx_t x) {
    idx_t lo = 0, hi = ((idx_t)1 << 32); /* 2^32 > sqrt(2^64-1) */
    idx_t res = 0;
    while (lo <= hi) {
        idx_t mid = lo + (hi - lo) / 2;
        unsigned __int128 sq = (unsigned __int128)mid * (unsigned __int128)mid;
        if (sq <= x) {
            res = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return res;
}

seq_t a(idx_t n) {
    /* find row r such that r(r+1)/2 <= n < (r+1)(r+2)/2 */
    idx_t t = (idx_t)((unsigned __int128)8 * n + 1);
    idx_t s = isqrt_u64(t);          /* s = floor(sqrt(8n+1)) */
    idx_t r = (s - 1) / 2;           /* row */

    /* start index of this row */
    unsigned __int128 prod = (unsigned __int128)r * (r + 1) / 2;
    idx_t start = (idx_t)prod;

    idx_t k = n - start;             /* column within the row */

    /* compute the triangle entry using the given formula */
    seq_t c1 = binomial(r, k);                                /* C(r,k) */
    seq_t val = 4 * c1 + 1;

    idx_t a1 = (r + k) / 2;                                       /* floor((r+k)/2) */
    seq_t c2 = binomial(a1, k);
    val -= 2 * c2;

    idx_t b1 = r - (k + 1) / 2;                                  /* r - floor((k+1)/2) */
    idx_t b2 = k / 2;                                            /* floor(k/2) */
    seq_t c3 = binomial(b1, b2);
    val -= 2 * c3;

    return val;
}
